def find_envs(value: str) -> list[str]:
    """Return the environment names described by the factor expressions in ``value``."""
    seen: set[str] = set()
    result: list[str] = []
    for factors, _ in expand_factors(value):
        if factors is not None:
            for group in factors:
                env = explode_factor(group)
                if env not in seen:
                    result.append(env)
                    seen.add(env)
    return result


